(function chirp() {
  const canvas = document.getElementById("chirp");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const wave = GW_STRAIN.map((v) => v / 1000);
  const n = wave.length - 1;
  let peak = 0;
  wave.forEach((v, i) => { if (Math.abs(v) > Math.abs(wave[peak])) peak = i; });
  let W = 0, H = 0;

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = W * dpr; canvas.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function path(upto, mid, A) {
    ctx.beginPath();
    for (let i = 0; i <= upto; i++) ctx.lineTo((i / n) * W, mid - wave[i] * A);
  }

  function draw(progress) {
    ctx.clearRect(0, 0, W, H);
    const mid = H / 2, A = H * 0.45;
    const upto = Math.floor(n * Math.min(progress, 1));

    // faint full template
    path(n, mid, A);
    ctx.strokeStyle = "rgba(120,160,255,0.12)";
    ctx.lineWidth = 1;
    ctx.stroke();

    // "observed" signal, turning gold towards the merger
    const xp = peak / n;
    const g = ctx.createLinearGradient(0, 0, W, 0);
    g.addColorStop(0, "rgba(90,169,255,0)");
    g.addColorStop(Math.max(xp - 0.45, 0.05), "rgba(90,169,255,0.75)");
    g.addColorStop(xp, "rgba(245,194,107,1)");
    g.addColorStop(1, "rgba(255,157,77,0.6)");
    path(upto, mid, A);
    ctx.strokeStyle = g;
    ctx.lineWidth = 1.8;
    ctx.shadowColor = "rgba(245,194,107,0.55)";
    ctx.shadowBlur = 10;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // flash at the moment of merger
    if (upto >= peak) {
      const age = (upto - peak) / (n - peak);
      const r = 6 + age * 26;
      const grd = ctx.createRadialGradient(xp * W, mid, 0, xp * W, mid, r);
      grd.addColorStop(0, "rgba(255,230,170," + (0.55 * (1 - age)) + ")");
      grd.addColorStop(1, "rgba(255,157,77,0)");
      ctx.fillStyle = grd;
      ctx.beginPath();
      ctx.arc(xp * W, mid, r, 0, Math.PI * 2);
      ctx.fill();
    }

    // detector "cursor"
    if (progress < 1) {
      const x = (upto / n) * W, y = mid - wave[upto] * A;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fillStyle = "#fff";
      ctx.shadowColor = "#f5c26b";
      ctx.shadowBlur = 16;
      ctx.fill();
      ctx.shadowBlur = 0;
    }
  }

  resize();
  window.addEventListener("resize", () => { resize(); if (reduce) draw(1); });
  if (reduce) { draw(1); return; }

  // play the 0.325 s of real signal in ~5.5 s (≈17× slower than real time)
  const DURATION = 5500, HOLD = 2500;
  let start = null;
  function frame(t) {
    if (start === null) start = t;
    const el = t - start;
    draw(el / DURATION);
    if (el > DURATION + HOLD) start = t;
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
